    {"id": "c_taban_donusum", "lang": "c", "course": "donanim", "title": "Sayı sistemi dönüştürücü (BTP239 alıştırmaları için)", "source": "btp239_h1_donusumler.pdf", "stdin": "37",
     "code": '#include <stdio.h>\n\n/* Onluk bir sayıyı 2, 8 ve 16 tabanına çevirir.\n   Bölme yöntemi: kalanlar aşağıdan yukarı okunur (ilk kalan LSB). */\nvoid yazdir(int n, int taban) {\n    char basamak[] = "0123456789ABCDEF";\n    char sonuc[40];\n    int k = 0;\n    if (n == 0) { printf("0"); return; }\n    while (n > 0) {\n        sonuc[k++] = basamak[n % taban];\n        n /= taban;\n    }\n    while (k > 0) putchar(sonuc[--k]);\n}\n\nint main() {\n    int n;\n    printf("Onluk sayı: ");\n    scanf("%d", &n);\n    printf("\\n(%d)10 = (", n); yazdir(n, 2);  printf(")2\\n");\n    printf("(%d)10 = (", n);   yazdir(n, 8);  printf(")8\\n");\n    printf("(%d)10 = (", n);   yazdir(n, 16); printf(")16\\n");\n    return 0;\n}\n'},
    {"id": "c_subnet_hesap", "lang": "c", "course": "ag", "title": "Subnet hesaplayıcı (AND işlemi ile ağ/broadcast)", "source": "hafta_5_ipv4_ipv6_ve_subnetting.pdf", "stdin": "192 168 1 130 26",
     "code": '#include <stdio.h>\n\n/* Girdi: IP\'nin 4 okteti ve prefix (örn: 192 168 1 130 26)\n   Ağ adresi = IP AND mask, Broadcast = ağ OR (ters mask) */\nvoid ip_yaz(unsigned int ip) {\n    printf("%u.%u.%u.%u", (ip >> 24) & 255, (ip >> 16) & 255, (ip >> 8) & 255, ip & 255);\n}\n\nint main() {\n    unsigned int a, b, c, d, prefix;\n    scanf("%u %u %u %u %u", &a, &b, &c, &d, &prefix);\n    unsigned int ip = (a << 24) | (b << 16) | (c << 8) | d;\n    unsigned int mask = prefix == 0 ? 0 : 0xFFFFFFFFu << (32 - prefix);\n    unsigned int ag = ip & mask;\n    unsigned int bc = ag | ~mask;\n    unsigned int host_bit = 32 - prefix;\n\n    printf("IP        : "); ip_yaz(ip);   printf(" /%u\\n", prefix);\n    printf("Mask      : "); ip_yaz(mask); printf("\\n");\n    printf("Ağ adresi : "); ip_yaz(ag);   printf("\\n");\n    printf("Broadcast : "); ip_yaz(bc);   printf("\\n");\n    if (host_bit >= 2) {\n        printf("İlk host  : "); ip_yaz(ag + 1); printf("\\n");\n        printf("Son host  : "); ip_yaz(bc - 1); printf("\\n");\n        printf("Kullanılabilir host: 2^%u - 2 = %u\\n", host_bit, (1u << host_bit) - 2);\n    }\n    return 0;\n}\n'},
